sys_variable_value.value:
(function execute(inputs, outputs) {
    
var multirow1 = inputs.dadosLucAtual;
var multirow2 = inputs.dadosModificar;

function removeDotsAndCommas(value) {
    return parseFloat(value.replace(/\./g, '').replace(',', '.'));
}

function formatToBrazilianNumber(value) {
    return value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).replace('.', ',');
}

var somaTotal = multirow1.reduce((acc, obj) => acc + removeDotsAndCommas(obj.area_anterior_m), 0);


multirow2.forEach(obj => {
    obj.area_total_da_luc_m_modificar = formatToBrazilianNumber(somaTotal);
});

multirow1 = multirow1.map(obj => {
    if (!multirow2.some(row => row.codigo_objeto_modificar === obj.luc_atual_v2)) {
        obj.area_anterior_m = "0,00";
    }
    return obj;
});


multirow1 = multirow1.filter(obj => 
    !multirow2.some(row => row.codigo_objeto_modificar === obj.luc_atual_v2)
);


gs.info("Multirow2 atualizado: " + JSON.stringify(multirow2));
gs.info("Multirow1 atualizado: " + JSON.stringify(multirow1));
outputs.outputmrvsatual = JSON.stringify(multirow1);
outputs.outputmrvsmodificar = JSON.stringify(multirow2);
outputs.string1 = JSON.stringify(multirow1);
outputs.string2 = JSON.stringify(multirow2);



})(inputs, outputs);

